"/><circle cx=\"5.5\" cy=\"6\" r=\"1.8\"/><circle cx=\"18.5\" cy=\"6\" r=\"1.8\"/><circle cx=\"5.5\" cy=\"18\" r=\"1.8\"/><circle cx=\"18.5\" cy=\"18\" r=\"1.8\"/><path d=\"M7 7l3.5 3.5M17 7l-3.5 3.5M7 17l3.5-3.5M17 17l-3.5-3.5\"/></svg></span>\n        <h2>Connected Progress</h2>\n        <p>Turn ideas into living systems that grow over time.</p>\n      </li>\n      <li class=\"pillar\">\n        <span class=\"ring\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 4l8 4.5-8 4.5-8-4.5L12 4z\"/><path d=\"M4 13l8 4.5 8-4.5\"/><path d=\"M4 17l8 4.5 8-4.5\"/></svg></span>\n        <h2>Persistent Context</h2>\n        <p>SOL remembers the big picture so you can keep moving.</p>\n      </li>\n      <li class=\"pillar\">\n        <span class=\"ring\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2.5v2.5M12 19v2.5M4.6 4.6l1.8 1.8M17.6 17.6l1.8 1.8M2.5 12H5M19 12h2.5M4.6 19.4l1.8-1.8M17.6 6.4l1.8-1.8\"/></svg></span>\n        <h2>Calm Planning</h2>\n        <p>A clearer mind today for a further tomorrow.</p>\n      </li>\n    </ul>\n\n    <p class=\"tagline\">Same thinking. A brighter tomorrow.</p>\n    <p class=\"mini-link\"><a href=\"evidence.html\">What is verified, and what is not</a></p>\n  </main>\n</div>\n</body>\n</html>\n";
