export default {async fetch(request){ const url=new URL(request.url);if(url.hostname!=="sol.foundercontrolroom.org")return new Response("Not found",{status:404});if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Not found",{status:404,headers:{"Cache-Control":"no-store"}});const headers={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff","X-Frame-Options":"DENY","Referrer-Policy":"strict-origin-when-cross-origin","Content-Security-Policy":"default-src 'none'; img-src 'self' data:; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; base-uri 'none'; frame-ancestors 'none'; form-action 'none'; script-src 'none'; connect-src 'none'"};const hit=routes[url.pathname];if(!hit)return new Response("Not found",{status:404,headers:{"Cache-Control":"no-store"}});return new Response(request.method==="HEAD"?null:hit[0],{status:200,headers:{...headers,...hit[1]}});}};
